/**
 * @file main.cpp
 * @brief Standalone SCE project example using find_package(SCE)
 *
 * This example demonstrates the recommended way to use SCE in production:
 *   1. find_package(SCE) to locate the installed library
 *   2. sce_add_state_machine() to generate C++ code from SCXML
 *   3. SCE::sce target to link with the library
 */

#include <iostream>

// Include generated state machine header
// Generated by sce_add_state_machine() CMake function
#include "traffic_light_sm.h"

int main() {
    std::cout << "=== SCE Standalone Project Example ===" << std::endl;
    std::cout << std::endl;

    // Create state machine instance
    // The generated class is in namespace SCE::Generated::<scxml_name>
    SCE::Generated::traffic_light::traffic_light sm;

    // Initialize the state machine (enters initial state)
    sm.initialize();

    std::cout << "Initial state: " << sm.getCurrentStateString() << std::endl;
    std::cout << std::endl;

    // Simulate timer events to cycle through states
    std::cout << "Sending timer events..." << std::endl;
    std::cout << std::endl;

    for (int i = 0; i < 6; ++i) {
        // Raise timer event
        sm.raiseEvent(SCE::Generated::traffic_light::traffic_light::Event::Timer);

        // Process the event
        sm.tick();

        // Show current state
        std::cout << "  [" << (i + 1) << "] State: " << sm.getCurrentStateString() << std::endl;
    }

    std::cout << std::endl;
    std::cout << "=== Example Complete ===" << std::endl;

    return 0;
}
